import { describe, expect, it } from 'vitest';
import { runInNewContext } from 'node:vm';
import { readFileSync, readdirSync } from 'node:fs';
import { parseReadiness } from './readiness';
// Shared checked-in contract fixture is generated by the local runner, not a live execution.
const text = readFileSync('ops/benjaire-production/fixtures/readiness-packet.json','utf8');
type Mutable = {events: {payload: {stage_owner: string; command?: string}}[]};
describe('local readiness import', () => {
  it('accepts the runner contract without authenticating it', () => expect(parseReadiness(text).fixture).toBe(true));
  for (const field of ['publish_authorized','external_actions','model_calls','revision','state','observed_at']) it(`rejects changed ${field}`, () => {
    const x = JSON.parse(text); x[field] = 'unauthorized'; expect(() => parseReadiness(JSON.stringify(x))).toThrow();
  });
  it('rejects broken routing, owners, duplicates and extra payload', () => {
    for (const edit of [(x: Mutable) => x.events.reverse(), (x: Mutable) => x.events[1].payload.stage_owner = 'other', (x: Mutable) => x.events[1] = x.events[0], (x: Mutable) => x.events[1].payload.command = 'run']) {
      const x = JSON.parse(text); edit(x); expect(() => parseReadiness(JSON.stringify(x))).toThrow();
    }
  });
  it('rejects invalid or oversized input', () => {
    for (const value of ['null','{',' '.repeat(32769)]) expect(() => parseReadiness(value)).toThrow();
  });
  it('export contains only inactive manual nodes without credentials', () => {
    expect(readdirSync('ops/benjaire-production/workflows')).toEqual(['readiness-manual.json']);
    const workflow = JSON.parse(readFileSync('ops/benjaire-production/workflows/readiness-manual.json','utf8'));
    expect(workflow.active).toBe(false);
    expect(workflow.nodes.map((n: {type: string}) => n.type)).toEqual(['n8n-nodes-base.manualTrigger','n8n-nodes-base.code']);
    expect(JSON.stringify(workflow)).not.toContain('credentials');
    const output = runInNewContext(`(function(){${workflow.nodes[1].parameters.jsCode}})()`, {}, {timeout:1000});
    expect(parseReadiness(JSON.stringify(output[0].json)).fixture).toBe(true);
  });
});
